const news=()=>`<section class="news" aria-labelledby="nl"><h2 id="nl">Join the Training Squad 💥</h2><p>One comic-style move breakdown + progression tip per week. Free, no spam, unsubscribe anytime. You will get a confirmation email.</p>
<form class="nlform" ${CFG.newsletterAction?`action="${CFG.newsletterAction}" method="post" target="_blank"`:'data-pending="1"'}><label class="sr" for="em">Email</label><input id="em" type="email" name="email" required placeholder="you@example.com" autocomplete="email"><button class="btn" type="submit">Sign me up!</button></form><p class="nlmsg" role="status"></p></section>`;
const page=({title,desc,url,body,ld,og})=>`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(desc)}"><link rel="canonical" href="${SITE}${url}"><meta property="og:site_name" content="Calisthenics Comics"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="${SITE}${url}"><meta property="og:image" content="${SITE}/og/${og||'home'}.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:type" content="image/jpeg"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="${SITE}/og/${og||'home'}.jpg"><meta name="theme-color" content="#ffe14d"><meta name="robots" content="max-image-preview:large"><meta name="google-site-verification" content="HU1pZHfBqs5W23rDxLTDDAYi99h0N_Kp7--cuQRu2Gw" /><link rel="icon" href="/favicon.svg"><link rel="alternate" type="text/plain" title="LLM summary" href="/llms.txt">${fonts}<link rel="stylesheet" href="/style.css">${(ld||[]).map(l=>`<script type="application/ld+json">${JSON.stringify(l)}</script>`).join('')}${analytics}</head><body><a class="skip" href="#main">Skip to content</a><header class="top"><a href="/" class="logo">CALISTHENICS <span>COMICS</span></a><nav aria-label="Main"><a href="/start/">Start here</a>${Object.keys(CAT).map(c=>`<a href="/c/${c}/">${CAT[c][0]}</a>`).join('')}<a href="/p/">Roadmaps</a><a href="/w/">Workouts</a></nav></header><main id="main">${body}${news()}</main><footer class="foot"><nav aria-label="Footer">${[...Object.keys(CAT).map(c=>`<a href="/c/${c}/">${CAT[c][0]} moves</a>`),'<a href="/start/">Beginner guide</a>','<a href="/30-day-challenge/">30-day challenge</a>','<a href="/over-50/">Calisthenics over 50</a>','<a href="/fat-loss/">Calisthenics for weight loss</a>','<a href="/build-muscle/">Build muscle</a>','<a href="/warm-up/">Warm-up routine</a>','<a href="/cool-down/">Cool-down routine</a>','<a href="/mobility/">Mobility for calisthenics</a>','<a href="/standards/">Strength standards</a>','<a href="/weighted/">Weighted calisthenics</a>','<a href="/holds/">Isometric holds</a>','<a href="/sets-reps/">Sets and reps</a>','<a href="/splits/">Workout splits</a>','<a href="/p/">Skill roadmaps</a>','<a href="/w/">Workout plans</a>','<a href="/muscles/">Exercises by muscle</a>','<a href="/levels/">Exercises by level</a>','<a href="/equipment/">Exercises by equipment</a>','<a href="/glossary/">Glossary</a>','<a href="/vs/">Move comparisons</a>'].join(' · ')} · <a href="/sitemap.xml">Sitemap</a> · <a href="/llms.txt">llms.txt</a></nav><p>Original comic art. Train smart: progress gradually and stop if you feel pain. Not medical advice.</p><p>© ${new Date().getFullYear()} Calisthenics Comics</p></footer><script src="/site.js" defer></script></body></html>`;
const ad=(label,size)=>`<aside class="ad" aria-label="Sponsor placeholder"><span>SPONSOR SLOT · ${label}</span><small>${size} · your brand here</small></aside>`;
const bar=d=>`<div class="power" role="img" aria-label="Difficulty ${d} of 10">${Array.from({length:10},(_,i)=>`<i class="${i<d?'on':''}"></i>`).join('')}</div>`;
const badge=m=>`<span class="lvl t-${m.tier.toLowerCase()}">LV ${m.diff} · ${m.tier}</span>`;
const pic=(m,sfx='',eager=false)=>`<picture><source type="image/webp" srcset="/art/${m.slug}-sm.webp 480w, /art/${m.slug}.webp 960w" sizes="${eager?'(max-width: 900px) 100vw, 560px':'(max-width: 640px) 100vw, 360px'}"><img src="/art/${m.slug}.jpg" width="960" height="540" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async" alt="Comic illustration of Vó Ferro, the Calisthenics Comics grandma, performing the ${esc(m.name)}"></picture>`;
const card=(m,sfx='')=>`<a class="card" href="/m/${m.slug}/" data-slug="${m.slug}" style="--c:${CAT[m.cat][1]}"><div class="art">${pic(m,sfx)}</div><div class="bubble"><h3>${esc(m.name)}</h3><p class="mus">${esc(m.muscles)}</p>${bar(m.diff)}<div class="tags">${badge(m)}<span class="tag">${CAT[m.cat][0]}</span>${m.weighted?'<span class="tag w">⚖ Weighted</span>':''}</div></div></a>`;
const faqHTML=f=>`<section class="faq"><h2>FAQ</h2>${f.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</section>`;
const faqLD=f=>({'@context':'https://schema.org','@type':'FAQPage',mainEntity:f.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))});
const crumbLD=items=>({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:items.map(([n,u],i)=>({'@type':'ListItem',position:i+1,name:n,item:SITE+u}))});

