const homeFaq=[['What is calisthenics?','Calisthenics is strength training using your own bodyweight — push-ups, pull-ups, squats, levers, handstands and more. Many moves can also be loaded with a vest or dip belt.'],['How are difficulty levels decided?',`Every move is rated 1–10 by the strength, skill and prerequisites it needs, grouped into six XP tiers from Rookie to Legend. There are ${M.length} movements in the library.`],['Where should a beginner start?','Start with Level 1–2 Rookie moves: wall push-ups, dead hangs, bodyweight squats, plank and glute bridges. Each move page links to its easier and harder progression.'],['Can you build muscle with calisthenics?','Yes. Progress by moving to harder variations or adding load (weighted vest or dip belt) once you hit the target reps.']];
const LV=[{id:'rookie',t:'Rookie',band:'Levels 1–2',kw:'Beginner',og:'incline-push-up',why:'Rookie moves are where everyone starts: wall and incline push-ups, hangs, squats and planks. No experience needed, just a floor, a wall and a bar or sturdy table.'},
{id:'brawler',t:'Brawler',band:'Levels 3–4',kw:'Beginner to intermediate',og:'push-up',why:'Brawler moves are the classic strength basics: full push-ups, your first pull-ups and chin-ups, dips, split squats and beginner balances like the crow pose. Own these and you have a real bodyweight foundation.'},
{id:'hero',t:'Hero',band:'Levels 5–6',kw:'Intermediate',og:'l-sit',why:'Hero moves add serious load and your first real skills: archer push-ups, ring dips, chest-to-bar pull-ups, L-sits, tuck planches and the freestanding handstand.'},
{id:'champion',t:'Champion',band:'Levels 7–8',kw:'Advanced',og:'muscle-up',why:'Champion moves are true calisthenics skills: muscle-ups, one-arm push-ups, pistol squats, dragon flags and the back lever, each taking months of practice.'},
{id:'titan',t:'Titan',band:'Level 9',kw:'Elite',og:'human-flag',why:'Titan moves are elite strength skills like the full front lever, the human flag, the straddle planche and the strict muscle-up. Expect years of steady training to get here.'},
{id:'legend',t:'Legend',band:'Level 10',kw:'Hardest',og:'full-planche',why:'Legend moves are the hardest bodyweight skills in the library, such as the full planche and the manna. Very few people ever reach them.'}];
