const TESTS=[['Push','push-up','Max strict push-ups','0–4: start with the incline push-up. 5–14: you are a Brawler, keep building. 15+: try the diamond or archer push-up.'],['Pull','pull-up','Max strict pull-ups (or dead hang time if you have none)','No pull-up yet: dead hangs, Australian rows and negatives. 1–5: pull-ups for low reps. 8+: chest-to-bar and harder.'],['Legs','bodyweight-squat','Max clean bodyweight squats','Under 20: own the squat first. 20–40: add lunges and split squats. 40+: work toward the pistol squat.'],['Core','plank','Plank hold time','Under 30 s: plank and dead bugs. 30–60 s: hollow body hold. Over 60 s: hanging knee raises and the L-sit.']];
